 ano integer NOT NULL REFERENCES estudo.web_bases(ano), versao integer NOT NULL CHECK(versao>=2),
 payload jsonb NOT NULL, contrato jsonb NOT NULL, criado_em timestamptz NOT NULL DEFAULT clock_timestamp(),
